import React, { useState } from 'react';
import styles from '../css/Weather.module.css';

const Weather = () => {
  const [city, setCity] = useState('');
  const [weatherData, setWeatherData] = useState(null);

  const API_KEY = '7ac5efbe309f3e7a20018760eb67b567';

  const translateCityName = async (cityName) => {
    const endpoint = 'https://libretranslate.de/translate';
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          q: cityName,
          source: 'ko', // 한국어
          target: 'en', // 영어
        }),
      });
      const data = await response.json();
      return data.translatedText; // 번역된 도시명 반환
    } catch (error) {
      console.error('번역 오류:', error);
      return cityName; // 번역 실패 시 원래 도시명 반환
    }
  };
  
  const fetchWeather = async () => {
    if (!city) {
      alert('도시 이름을 입력하세요.');
      return;
    }

    // 번역된 도시명 얻기 (비동기 처리 필요)
    const translatedCity = await translateCityName(city);

    try {
      const response = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?q=${translatedCity}&appid=${API_KEY}&units=metric&lang=kr`
      );
      const data = await response.json();
      console.log(data); // 데이터를 콘솔에 출력
      if (data.cod === 200) {
        setWeatherData(data);
      } else {
        alert('도시를 찾을 수 없습니다!');
        setWeatherData(null);
      }
    } catch (error) {
      console.error('날씨 데이터를 가져오는 중 오류가 발생했습니다:', error);
    }
  };

  return (
    <div className={styles.container}>
      <h2>날씨 정보</h2>
      <input
        className={styles.input}
        type="text"
        placeholder="도시 이름 입력"
        value={city}
        onChange={(e) => setCity(e.target.value)}
      />
      <button className={styles.button} onClick={fetchWeather}>날씨 정보 가져오기</button>
      {weatherData && (
        <div className={styles['weather-info']}>
          <p>온도: {Math.round(weatherData.main.temp)}°C</p> {/* 온도 소수점 없이 표시 */}
          <p>날씨: {weatherData.weather[0].description}</p>
        </div>
      )}
    </div>
  );
};

export default Weather;
